module combinatorial(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [3:0] M,\n    input wire [3:0] K,\n    output reg [31:0] result,\n    output reg done\n);\n    \n    // Local parameters for FSM states\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] SETUP       = 3'd1;\n    localparam [2:0] COMPUTE_I   = 3'd2;\n    localparam [2:0] COMPUTE_J   = 3'd3;\n    localparam [2:0] COMPUTE_C   = 3'd4;\n    localparam [2:0] COMPUTE_J_END = 3'd5;\n    localparam [2:0] COMPUTE_I_END = 3'd6;\n    localparam [2:0] DONE_STATE  = 3'd7;\n    \n    reg [2:0] state, next_state;\n    \n    // DP arrays\n    reg [31:0] dp_prev [0:8];\n    reg [31:0] dp_curr [0:8];\n    \n    // Counters\n    reg [3:0] i_counter;\n    reg [3:0] j_counter;\n    reg [3:0] c_counter;\n    reg [3:0] K_reg;\n    reg [3:0] N_reg;\n    reg [3:0] M_reg;\n    \n    // Temporary registers\n    reg [31:0] sum_temp;\n    reg [3:0] current_max_c;\n    \n    // Cycle counter to prevent infinite loops\n    reg [9:0] cycle_count;\n    localparam [9:0] MAX_CYCLES = 10'd1000;\n    \n    integer idx;  // Loop variable\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            i_counter <= 3'd0;\n            j_counter <= 4'd0;\n            c_counter <= 4'd0;\n            sum_temp <= 32'd0;\n            current_max_c <= 4'd0;\n            cycle_count <= 10'd0;\n            for (idx = 0; idx <=8; idx = idx + 1) begin\n                dp_prev[idx] <= 32'd0;\n                dp_curr[idx] <= 32'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 10'd0;\n                    if (start) begin\n                        state <= SETUP;\n                    end\n                end\n                \n                SETUP: begin\n                    // Capture inputs\n                    N_reg <= N;\n                    M_reg <= M;\n                    K_reg <= K;\n                    \n                    // Initialize dp_prev\n                    dp_prev[0] <= 32'd1;\n                    for (idx = 1; idx <=8; idx = idx + 1) begin\n                        dp_prev[idx] <= 32'd0;\n                    end\n                    \n                    i_counter <= 3'd1;  // Start at type 1\n                    state <= COMPUTE_I;\n                    cycle_count <= cycle_count + 10'd1;\n                end\n                \n                COMPUTE_I: begin\n                    j_counter <= 4'd0;\n                    state <= COMPUTE_J;\n                    cycle_count <= cycle_count + 10'd1;\n                end\n                \n                COMPUTE_J: begin\n                    c_counter <= 4'd0;\n                    sum_temp <= 32'd0;\n                    \n                    // Calculate current_max_c = min(M_reg, j_counter)\n                    current_max_c <= (j_counter < M_reg) ? j_counter : M_reg;\n                    \n                    state <= COMPUTE_C;\n                    cycle_count <= cycle_count + 10'd1;\n                end\n                \n                COMPUTE_C: begin\n                    if (c_counter <= current_max_c) begin\n                        sum_temp <= sum_temp + dp_prev[j_counter - c_counter];\n                        c_counter <= c_counter + 4'd1;\n                    end else begin\n                        state <= COMPUTE_J_END;\n                    end\n                    cycle_count <= cycle_count + 10'd1;\n                    if (cycle_count >= MAX_CYCLES) state <= DONE_STATE;\n                end\n                \n                COMPUTE_J_END: begin\n                    dp_curr[j_counter] <= sum_temp % 32'd1000007;\n                    j_counter <= j_counter + 4'd1;\n                    if (j_counter > K_reg) begin  // All j processed\n                        state <= COMPUTE_I_END;\n                    end else begin\n                        state <= COMPUTE_J;\n                    end\n                    cycle_count <= cycle_count + 10'd1;\n                    if (cycle_count >= MAX_CYCLES) state <= DONE_STATE;\n                end\n                \n                COMPUTE_I_END: begin\n                    // Copy dp_curr to dp_prev\n                    for (idx = 0; idx <=8; idx = idx + 1) begin\n                        dp_prev[idx] <= dp_curr[idx];\n                    end\n                    \n                    if (i_counter < N_reg) begin\n                        i_counter <= i_counter + 3'd1;\n                        state <= COMPUTE_I;\n                    end else begin\n                        result <= dp_prev[K_reg];\n                        state <= DONE_STATE;\n                    end\n                    cycle_count <= cycle_count + 10'd1;\n                    if (cycle_count >= MAX_CYCLES) state <= DONE_STATE;\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule